(() => {
 const data=window.SCHOOL_DATA,main=document.getElementById('main'),params=new URLSearchParams(location.search),all=data.lessons||[],topics=data.lessonTopics||[];
 // 教材工坊、教案書屋都併進山海探索站，舊網址轉到主題總覽
 if(params.get('view')==='materials'){location.replace('lessons.html');return;}
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const url=l=>'lessons.html?lesson='+encodeURIComponent(l.id),read=l=>'reader.html?lesson='+encodeURIComponent(l.id),topicURL=t=>'lessons.html?topic='+encodeURIComponent(t);
 const media=window.SCHOOL_MEDIA||{lessons:{},topics:{}},bands=['低年級','中年級','高年級'],progress=Object.fromEntries((data.curriculum115?.progress||[]).map(p=>[p.band,p.label]));
 const linkList=list=>`<ul>${list.map(m=>`<li><a href="${esc(m.url)}" target="_blank" rel="noopener"><span class="media-kind media-${m.type}">${m.type==='padlet'?'Padlet':'影片'}</span><span class="media-label">${esc(m.label)}</span>${m.star?'<span class="media-star">推薦</span>':''}<span class="media-go" aria-hidden="true">↗</span></a></li>`).join('')}</ul>`;
 const cover=(l,thumb=false)=>l.cover?data.assets[l.cover][thumb?'thumb':'src']:l.coverPage;
 const term=l=>`${l.year}${l.semester===1?'上':'下'}`;
 const heading=(title,description,trail=[])=>`<header class="page-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span>${trail.map(([t,h])=>`<a href="${h}">${esc(t)}</a><span>/</span>`).join('')}<span>${esc(title)}</span></div><h1>${esc(title)}</h1><p>${esc(description)}</p></header>`;
 const order=(a,b)=>bands.indexOf(a.band)-bands.indexOf(b.band)||a.semester-b.semester||a.start-b.start;
 const once=(list,key)=>{const seen=new Set();return list.filter(x=>x&&!seen.has(key(x))&&seen.add(key(x)));};
 const byId=id=>data.resources.find(r=>r.id===id),unitOf=l=>l?.resource?byId(l.resource):null;
 const storiesOf=u=>u?u.related.map(byId).filter(r=>r&&r.section==='課程與教材'&&['活動紀錄','學生作品'].includes(r.type)):[];
 // 一課或一個主題的整合資料：對應的課程單元就是教材；單元連到的活動紀錄、學生作品和學習步驟卡算作品；照片、影片與 Padlet 合併後去重
 const collect=(lessons,unitList,extra=[])=>{const units=once(unitList,u=>u.id),stories=once(units.flatMap(storiesOf),s=>s.id),linked=new Set([...units,...stories].map(r=>r.id)),ids=new Set(lessons.map(l=>l.id)),list=once([...lessons.flatMap(l=>(media.lessons[l.id]||[]).map(m=>({...m,from:l}))),...extra],m=>m.url);return {lessons,units,stories,journeys:(data.journeys||[]).filter(j=>j.lessons.some(id=>ids.has(id))||j.resources.some(id=>linked.has(id))),photos:[...new Set([...lessons.flatMap(l=>[l.cover,...(l.photos||[])]),...units.flatMap(u=>u.photos||[]),...stories.flatMap(s=>s.photos||[])])].filter(id=>id&&data.assets[id]),padlets:list.filter(m=>m.type==='padlet'),videos:list.filter(m=>m.type!=='padlet')};};
 const kit=l=>collect([l],[unitOf(l)]);
 // 主題：主題裡每一課的資料，加上同主題的影片與 Padlet；沒有教案對應、或也教到這個主題的課程單元列在 data.lessonTopicUnits
 const topicKit=t=>{const ls=all.filter(l=>l.topic===t).sort(order);return collect(ls,[...ls.map(unitOf),...(data.lessonTopicUnits?.[t]||[]).map(byId)],media.topics[t]||[]);};
 const works=k=>k.stories.length+k.journeys.length;
 const kitLine=(k,plans=false)=>{const b=[k.videos.length&&`影片 ${k.videos.length}`,k.photos.length&&`照片 ${k.photos.length}`,k.units.length&&(plans?`教材 ${k.units.length}`:'教材'),works(k)&&`作品 ${works(k)}`,k.padlets.length&&`Padlet ${k.padlets.length}`,plans&&`教案 ${k.lessons.length}`].filter(Boolean);return b.length?`<p class="lesson-kit">${b.map(x=>`<span>${esc(x)}</span>`).join('')}</p>`:'';};
 const card=(l,label=l.topic)=>`<article class="resource-card visual-card lesson-card"><a class="card-image ${l.cover?'':'image-contain'}" href="${url(l)}" tabindex="-1" aria-hidden="true"><img src="${esc(cover(l,true))}" alt="" loading="lazy"></a><div class="card-copy"><span class="type-label">${esc(label)}</span><h3><a href="${url(l)}">${esc(l.title)}</a></h3><div class="meta-line"><span>${term(l)}</span><span>${esc(l.course)}</span>${l.periods?`<span>${l.periods} 節</span>`:''}</div><p>${esc(l.summary)}</p>${kitLine(kit(l))}<div class="card-bottom"><a class="text-link" href="${url(l)}">打開這一課 →</a><a class="text-link" href="${read(l)}">翻閱教案 ${l.end-l.start+1} 頁 ↗</a></div></div></article>`;
 const workCard=(href,img,type,title,meta)=>`<article class="resource-card visual-card"><a class="card-image" href="${href}" tabindex="-1" aria-hidden="true"><img src="${esc(img)}" alt="" loading="lazy" decoding="async"></a><div class="card-copy"><span class="type-label">${esc(type)}</span><h3><a href="${href}">${esc(title)}</a></h3><div class="meta-line">${meta.filter(Boolean).map(m=>`<span>${esc(m)}</span>`).join('')}</div></div></article>`;
 const ytThumb=u=>{const id=(String(u).match(/(?:youtu\.be\/|[?&]v=|\/(?:shorts|embed|live)\/)([\w-]{11})/)||[])[1];return id?`https://i.ytimg.com/vi/${id}/hqdefault.jpg`:'';};
 const heads=(eyebrow,title,note,id='')=>`<div class="album-heading"><div><p class="eyebrow">${eyebrow}</p><h2${id?` id="${id}"`:''}>${esc(title)}</h2></div>${note?`<p>${note}</p>`:''}</div>`;

 // 一、影音資料：課程影片（YouTube 縮圖，點了在網站裡播放；Facebook 影片開新分頁）和課程照片
 const videoCards=(list,from)=>`<div class="video-grid">${list.map(m=>{const img=ytThumb(m.url)||(m.from?.cover?data.assets[m.from.cover].thumb:'');return `<a class="video-card" href="${esc(m.url)}" target="_blank" rel="noopener"><span class="video-thumb">${img?`<img src="${esc(img)}" alt="" loading="lazy" decoding="async">`:''}<b aria-hidden="true">▶</b></span><span class="video-copy"><strong>${esc(m.label)}</strong><small>${from&&m.from?esc(m.from.band+'・'+m.from.title)+' · ':''}${/facebook\.com/.test(m.url)?'Facebook ↗':'YouTube'}</small></span></a>`;}).join('')}</div>`;
 const videoLead=list=>{const fb=list.filter(m=>/facebook\.com/.test(m.url)).length;return !fb?'點了就在網站裡播放。':fb===list.length?'點了會開新分頁。':'YouTube 影片在網站裡播放，Facebook 影片會開新分頁。';};
 const mediaSection=(k,prefix,from)=>k.videos.length||k.photos.length?`<section class="kit-section" id="${prefix}-media">${heads('VIDEOS &amp; PHOTOS','影音資料',[k.videos.length&&`${k.videos.length} 部影片`,k.photos.length&&`${k.photos.length} 張照片`].filter(Boolean).join(' · '))}${k.videos.length?`<div class="kit-sub" id="${prefix}-videos"><h3>課程影片</h3><p class="kit-lead">${videoLead(k.videos)}</p>${videoCards(k.videos,from)}</div>`:''}${k.photos.length?`<div class="kit-sub story-album" id="${prefix}-photos"><h3>課程照片</h3><p class="kit-lead">點照片可以放大。</p><div class="photo-gallery" id="photo-gallery"></div><button type="button" class="pill gallery-more" id="gallery-more">再看更多照片</button></div>`:''}</section>`:'';
 const bindGallery=(photos,label)=>{const grid=document.getElementById('photo-gallery'),more=document.getElementById('gallery-more');if(!grid)return;let shown=24;const draw=()=>{grid.innerHTML=photos.slice(0,shown).map((id,i)=>{const a=data.assets[id];return `<button type="button" class="photo-open" data-photo="${esc(id)}" data-caption="${esc(label)}｜課程照片 ${i+1}" aria-label="放大${esc(label)}照片${i+1}"><img src="${esc(a.thumb)}"${a.width&&a.height?` width="${a.width}" height="${a.height}"`:''} alt="${esc(label)}的課程照片" loading="lazy" decoding="async"><span>放大觀看 ↗</span></button>`;}).join('');more.hidden=shown>=photos.length;more.textContent=`再看更多照片（${Math.max(0,photos.length-shown)} 張）`;};more.onclick=()=>{shown+=24;draw();};draw();};

 // 二、課程架構：依這個主題的課程內容產生；主題 → 年段 → 每一課與學習重點。還沒整理重點的課，取學習目標的前三條
 const goals=l=>l.points||String(l.objectives||'').split(/\n(?=\s*(?:●|\d+\.))/).map(s=>s.replace(/^\s*(?:●|\d+\.)\s*/,'').replace(/([一-鿿，、（）])\s+(?=[一-鿿，、（）])/g,'$1').replace(/\s+/g,' ').replace(/^(?:學生)?能/,'').replace(/[。.]\s*$/,'').trim()).filter(Boolean).slice(0,3);
 const node=(href,meta,title,points,current)=>`<li class="tree-node${current?' is-current':''}"><p class="tree-meta">${esc(meta)}</p><h4><a href="${href}"${current?' aria-current="page"':''}>${esc(title)}</a></h4>${points.length?`<ul class="tree-points">${points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}</li>`;
 const structure=(t,k,prefix,current)=>{const nodes=[...k.lessons.map(l=>({band:l.band,semester:l.semester,start:l.start,html:node(url(l),`${term(l)}・${l.course}${l.periods?`・${l.periods} 節`:''}`,l.title,goals(l),current===l.id)})),...k.units.filter(u=>!all.some(l=>l.resource===u.id)).map(u=>({band:u.bands[0],semester:u.semester,start:1e9,html:node('resource.html?id='+encodeURIComponent(u.id),`${u.year}${u.semester===1?'上':'下'}・課程單元`,u.title,u.points||[],false)}))],used=bands.filter(b=>nodes.some(n=>n.band===b)),flow=data.lessonTopicFlows?.[t];
  return `<section class="kit-section" id="${prefix}-structure">${heads('COURSE STRUCTURE',current?`課程架構：${t}`:'課程架構',current?'綠框是這一課':'依這個主題的課程內容整理')}<div class="course-tree"><div class="tree-root"><strong>${esc(t)}</strong>${flow?`<p>${esc(flow)}</p>`:''}</div><ol class="tree-bands${used.length===1?' is-single':''}" style="--bands:${used.length}">${used.map(b=>`<li class="tree-band"><h3 class="tree-band-head"><b>${b}</b>${progress[b]?`<span>${esc(progress[b])}</span>`:''}</h3><ul class="tree-nodes">${nodes.filter(n=>n.band===b).sort((x,y)=>x.semester-y.semester||x.start-y.start).map(n=>n.html).join('')}</ul></li>`).join('')}</ol></div>${current?`<a class="text-link" href="${topicURL(t)}#theme-structure">看「${esc(t)}」主題的完整內容 →</a>`:''}</section>`;};

 // 三、教材：對應的課程單元
 const materials=(units,prefix)=>units.length?`<section class="kit-section" id="${prefix}-material">${heads('TEACHING MATERIALS','教材',units.length>1?`${units.length} 個課程單元`:'')}${units.map(u=>`<article class="kit-unit-card"><div class="kit-unit-head"><div><p class="tree-meta">${u.year}${u.semester===1?'上':'下'}・${esc(u.bands.join('、'))}・課程單元</p><h3>${esc(u.title)}</h3></div><a class="text-link" href="resource.html?id=${esc(u.id)}">看單元頁 →</a></div><p class="kit-lead">${esc(u.summary)}</p><dl class="kit-unit">${(u.sections||[]).map(s=>`<div><dt>${esc(s.title)}</dt><dd>${esc(s.text)}</dd></div>`).join('')}</dl></article>`).join('')}</section>`:'';

 // 四、學生作品：活動紀錄、學生作品、學習步驟卡，再來是 Padlet 學習歷程原板
 const worksSection=(k,prefix)=>works(k)||k.padlets.length?`<section class="kit-section" id="${prefix}-works">${heads('STUDENT WORKS','學生作品',[works(k)&&`${works(k)} 項作品與學習紀錄`,k.padlets.length&&`${k.padlets.length} 個 Padlet 原板`].filter(Boolean).join(' · '))}${works(k)?`<div class="resource-grid">${k.stories.map(s=>workCard(`resource.html?id=${esc(s.id)}`,data.assets[s.cover]?.thumb||'',s.type,s.title,[term(s),`${s.photos.length} 張影像`])).join('')}${k.journeys.map(j=>workCard(`journeys.html#${esc(j.id)}`,data.assets[j.steps.find(st=>data.assets[st.photo])?.photo]?.thumb||'','學習步驟卡',j.title,[j.term,j.band,`${j.steps.length} 個步驟`])).join('')}</div>`:''}${k.padlets.length?`<div class="media-links kit-sub" id="${prefix}-padlet"><h3>Padlet 學習歷程原板</h3><p>班級的學習歷程原板，點了會開新分頁。</p>${linkList(k.padlets)}</div>`:''}</section>`:'';

 const jump=()=>{const target=location.hash&&document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target){const root=document.documentElement;root.style.scrollBehavior='auto';target.scrollIntoView();root.style.scrollBehavior='';}};
 const kitNav=(label,items)=>`<nav class="kit-nav" aria-label="${label}"><span>${label}</span>${items.filter(Boolean).map(([id,text])=>`<a href="#${id}">${esc(text)}</a>`).join('')}</nav>`;
 document.querySelector('a[href="lessons.html"]')?.setAttribute('aria-current','page');

 // 一課的頁面：和主題頁同樣的順序，最後才是教案
 if(params.has('lesson')){
  const l=all.find(x=>x.id===params.get('lesson'));
  if(!l){main.innerHTML=heading('換一堂課，繼續探索','回到山海探索站，挑選一個主題開始。')+'<a class="button" href="lessons.html">返回山海探索站</a>';return;}
  const k=kit(l),pages=l.end-l.start+1;document.title=l.title+'｜Salimpo 山海探索站';
  const plan=`<section class="kit-section" id="lesson-plan">${heads('LESSON PLAN','教案',`<a class="text-link" href="${read(l)}">閱讀全部 ${pages} 頁 →</a>`)}<div class="story-layout"><div><section class="story-chapter"><p class="chapter-number">01 / LET'S LEARN</p><h3>這堂課，從這裡開始</h3><p>${esc(l.summary)}</p></section>${l.objectives?`<section class="story-chapter"><p class="chapter-number">02 / LEARNING GOALS</p><h3>這堂課想學會什麼？</h3><p class="lesson-excerpt">${esc(l.objectives)}</p></section>`:''}${l.vocabulary?`<section class="story-chapter"><p class="chapter-number">03 / WORDS IN OUR LIFE</p><h3>教案裡的族語與關鍵詞</h3><p class="lesson-excerpt">${esc(l.vocabulary)}</p></section>`:''}</div><aside class="story-reading"><p class="eyebrow">OPEN THIS LESSON</p><h3>翻開這份教案</h3><a class="reading-entry" href="${read(l)}"><span>完整教學內容</span><strong>閱讀${esc(l.title)}教案</strong><small>${pages} 頁 · 主題內搜尋 ↗</small></a><a class="text-link" href="${topicURL(l.topic)}">← 回「${esc(l.topic)}」主題</a></aside></div><div class="lesson-page-preview">${[l.start,Math.min(l.end,l.start+1)].map(n=>`<a href="reader.html?lesson=${esc(l.id)}&page=${n}" aria-label="閱讀${esc(l.title)}教案第${n-l.start+1}頁"><img src="media/${esc(l.book)}/${String(n).padStart(3,'0')}.webp" alt="${esc(l.title)}教案第${n-l.start+1}頁" loading="lazy"></a>`).join('')}</div></section>`;
  const nav=kitNav('這一課有',[(k.videos.length||k.photos.length)&&['lesson-media','影音資料'],['lesson-structure','課程架構'],k.units.length&&['lesson-material','教材'],(works(k)||k.padlets.length)&&['lesson-works','學生作品'],['lesson-plan',`教案 ${pages} 頁`]]);
  main.innerHTML=heading(l.title,l.summary,[['山海探索站','lessons.html'],[l.topic,topicURL(l.topic)]])+`<article class="page-body rich-story lesson-detail"><div class="story-facts"><span>${esc(l.band)}</span><span>${term(l)}</span><span>${esc(l.course)}</span><span>${esc(l.topic)}</span>${l.periods?'<span>'+l.periods+' 節</span>':''}<span>${pages} 頁教案</span></div>${nav}${mediaSection(k,'lesson',false)}${structure(l.topic,topicKit(l.topic),'lesson',l.id)}${materials(k.units,'lesson')}${worksSection(k,'lesson')}${plan}<section class="story-related"><h2>同一個主題，還有這些課</h2><div class="resource-grid">${all.filter(x=>x.id!==l.id&&x.topic===l.topic).sort(order).slice(0,4).map(x=>card(x,x.band)).join('')}</div><a class="text-link" href="${topicURL(l.topic)}">看「${esc(l.topic)}」主題的全部影音、教材、作品與教案 →</a></section></article>`;
  bindGallery(k.photos,l.title);jump();return;
 }

 // 主題頁：影音資料 → 課程架構 → 教材 → 學生作品 → 教案
 if(params.has('topic')){
  const t=params.get('topic');
  if(!topics.includes(t)){main.innerHTML=heading('換一個主題，繼續探索','回到山海探索站，挑選一個主題開始。',[['山海探索站','lessons.html']])+'<a class="button" href="lessons.html">返回山海探索站</a>';return;}
  const k=topicKit(t),total=k.lessons.every(l=>l.periods)?k.lessons.reduce((n,l)=>n+l.periods,0):0;document.title=t+'｜Salimpo 山海探索站';
  const nav=kitNav('這個主題有',[(k.videos.length||k.photos.length)&&['theme-media','影音資料'],['theme-structure','課程架構'],k.units.length&&['theme-material','教材'],(works(k)||k.padlets.length)&&['theme-works','學生作品'],['theme-plans',`教案 ${k.lessons.length} 份`]]);
  const plans=`<section class="kit-section" id="theme-plans">${heads('LESSON PLANS','教案',`${k.lessons.length} 份教案 · 點進去看每一課`)}<div class="resource-grid">${k.lessons.map(l=>card(l,l.band)).join('')}</div></section>`;
  main.innerHTML=heading(t,data.lessonTopicFlows?.[t]||'',[['山海探索站','lessons.html']])+`<article class="page-body rich-story lesson-detail theme-detail"><div class="story-facts">${bands.filter(b=>k.lessons.some(l=>l.band===b)).map(b=>`<span>${b}</span>`).join('')}<span>${[...new Set(k.lessons.map(term))].join('・')}</span><span>${k.lessons.length} 份教案</span>${total?`<span>共 ${total} 節</span>`:''}</div>${nav}${mediaSection(k,'theme',true)}${structure(t,k,'theme')}${materials(k.units,'theme')}${worksSection(k,'theme')}${plans}<section class="story-related"><h2>其他主題</h2><nav class="theme-switch" aria-label="其他主題">${topics.map(x=>`<a href="${topicURL(x)}"${x===t?' aria-current="page"':''}>${esc(x)}</a>`).join('')}</nav></section></article>`;
  bindGallery(k.photos,t);jump();return;
 }

 // 總覽：先挑主題；也可以直接找一堂課
 const themeCard=t=>{const k=topicKit(t),l=k.lessons.find(x=>x.cover),step=k.journeys.flatMap(j=>j.steps).find(s=>data.assets[s.photo]),yt=k.videos.map(m=>ytThumb(m.url)).find(Boolean),img=l?data.assets[l.cover].thumb:k.photos[0]?data.assets[k.photos[0]].thumb:step?data.assets[step.photo].thumb:yt||k.lessons[0].coverPage,href=topicURL(t);return `<article class="resource-card visual-card lesson-card theme-card"><a class="card-image ${img===k.lessons[0].coverPage?'image-contain':''}" href="${href}" tabindex="-1" aria-hidden="true"><img src="${esc(img)}" alt="" loading="lazy" decoding="async"></a><div class="card-copy"><span class="type-label">${bands.filter(b=>k.lessons.some(x=>x.band===b)).join('・')}</span><h3><a href="${href}">${esc(t)}</a></h3><p>${esc(data.lessonTopicFlows?.[t]||'')}</p>${kitLine(k,true)}<div class="card-bottom"><a class="text-link" href="${href}">打開這個主題 →</a></div></div></article>`;};
 document.title='山海探索站｜Salimpo 學校資料館';
 main.innerHTML=heading('山海探索站','挑一個主題走進山海課程：每個主題依序看影音資料、課程架構、教材、學生作品，最後是教案。')+`<div class="page-body"><section class="kit-group">${heads(`${topics.length} THEMES`,'依主題看課程',`${all.length} 份教案 · 點一個主題開始`)}<div class="resource-grid theme-grid">${topics.map(themeCard).join('')}</div></section><section class="kit-group lesson-search">${heads('FIND A LESSON','直接找一堂課','')}<form class="filters lesson-filters" role="search" aria-label="搜尋教案"><label class="filter-field" for="lesson-query">找一堂課<input id="lesson-query" type="search" placeholder="例如：野番茄、家屋、族語"></label><label class="filter-field" for="lesson-band">年段<select id="lesson-band"><option value="">全部年段</option>${bands.map(b=>`<option>${b}</option>`).join('')}</select></label><label class="filter-field" for="lesson-term">學期<select id="lesson-term"><option value="">全部學期</option><option value="1">114上學期</option><option value="2">114下學期</option></select></label></form><div class="results-top"><p id="lesson-count" class="results-count" role="status" aria-live="polite"></p><button type="button" class="reset-button" id="lesson-all">列出全部教案</button><button type="button" class="reset-button" id="lesson-reset">重新探索</button></div><div id="lesson-results"></div></section><section class="lesson-more-books"><h2>教案旁邊的更多靈感</h2><div class="related-list"><a href="resource.html?id=PLAN-002#course-map"><span>全校課程地圖：115・116螺旋式課程</span><span>課程架構屋 →</span></a><a href="journeys.html"><span>我們怎麼學：一步一步的學習步驟卡</span><span>步驟卡 →</span></a><a href="reader.html?book=report114a&page=555"><span>上學期評量規準與學習單</span><span>閱讀內容 ↗</span></a><a href="reader.html?book=report114b"><span>山海學習全紀錄</span><span>完整成果 ↗</span></a></div></section></div>`;
 let showAll=false;const query=document.getElementById('lesson-query'),band=document.getElementById('lesson-band'),semester=document.getElementById('lesson-term');query.value=params.get('q')||'';band.value=params.get('band')||'';semester.value=params.get('semester')||'';
 function draw(){const q=query.value.trim().toLocaleLowerCase(),active=showAll||q||band.value||semester.value,list=all.filter(l=>(!band.value||l.band===band.value)&&(!semester.value||String(l.semester)===semester.value)&&(!q||[l.title,l.summary,l.topic,l.course,l.vocabulary,l.objectives,...(l.points||[])].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>b.semester-a.semester||a.start-b.start);document.getElementById('lesson-count').textContent=active?`找到 ${list.length} 份教案 · 共 ${all.length} 份`:`${topics.length} 個主題 · ${all.length} 份教案，可以用關鍵字、年段或學期找`;document.getElementById('lesson-all').hidden=active;document.getElementById('lesson-results').innerHTML=!active?'':list.length?bands.map(b=>{const rows=list.filter(l=>l.band===b);return rows.length?`<section class="lesson-band-group"><div class="album-heading"><h3>${b}的學習旅程</h3><p>${rows.length} 份教案</p></div><div class="resource-grid">${rows.map(l=>card(l)).join('')}</div></section>`:'';}).join(''):'<div class="empty-state"><h3>換個關鍵字，再找找看</h3><p>試試其他關鍵字或年段。</p></div>';const u=new URL(location.href);u.search='';for(const [k,v] of [['q',query.value],['band',band.value],['semester',semester.value]])if(v)u.searchParams.set(k,v);history.replaceState(null,'',u);}
 main.querySelector('form').onsubmit=e=>{e.preventDefault();draw();};query.oninput=draw;band.onchange=draw;semester.onchange=draw;document.getElementById('lesson-all').onclick=()=>{showAll=true;draw();};document.getElementById('lesson-reset').onclick=()=>{showAll=false;query.value='';band.value='';semester.value='';draw();};draw();
})();
